item.text:
{
  "characters": [
    {
      "name": "Mara",
      "description": "A freckled ferryman in a faded coat.",
      "backstory": "She returned to restore her father's ferry."
    },
    {
      "name": "Ellis",
      "description": "A lanky gardener with silver curls.",
      "backstory": "He grows flowers for sailors coming home."
    },
    {
      "name": "Kit",
      "description": "A small, bespectacled apprentice boatwright.",
      "backstory": "They hope to build their first seaworthy boat."
    }
  ],
  "npcs": [
    {
      "name": "Nell",
      "description": "A stout baker with floury sleeves.",
      "backstory": "She inherited the harbour's oldest bakery.",
      "relationships": "Mara's aunt; feeds Ellis and mentors Kit."
    },
    {
      "name": "Orin",
      "description": "A weathered keeper with a copper cane.",
      "backstory": "He tends the lighthouse after decades at sea.",
      "relationships": "Nell's brother; guides Mara and teaches Kit knots."
    },
    {
      "name": "Bea",
      "description": "A cheerful postwoman in yellow boots.",
      "backstory": "She stayed after delivering one storm-delayed letter.",
      "relationships": "Ellis's friend; brings Nell letters and Orin groceries."
    }
  ]
}
